functions.protect_nonzero_quiz_score_on_update:
CREATE OR REPLACE FUNCTION public.protect_nonzero_quiz_score_on_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(OLD.score_obtenu, 0) > 0
     AND COALESCE(NEW.score_obtenu, 0) <= 0 THEN
    NEW.score_obtenu := OLD.score_obtenu;

    IF COALESCE(NEW.score_max, 0) > 0 THEN
      NEW.note_sur_20 := ROUND(((NEW.score_obtenu / NEW.score_max) * 20)::numeric, 1);
    ELSE
      NEW.note_sur_20 := COALESCE(OLD.note_sur_20, NEW.note_sur_20);
    END IF;

    NEW.reussi := COALESCE(OLD.reussi, NEW.reussi);
  END IF;

  RETURN NEW;
END;
$function$

functions.trg_examens_blancs_6_sur_6:
CREATE OR REPLACE FUNCTION public.trg_examens_blancs_6_sur_6()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  BEGIN
    IF TG_TABLE_NAME = 'apprenant_quiz_results' THEN
      IF NEW.quiz_type = 'examen_blanc' THEN
        PERFORM public.examens_blancs_valider_si_complet(NEW.apprenant_id, NEW.quiz_id);
      END IF;
    ELSIF TG_TABLE_NAME = 'exam_attempts_v2' THEN
      IF NEW.etat = 'terminee' AND NOT coalesce(NEW.is_test, false)
         AND (TG_OP = 'INSERT' OR OLD.etat IS DISTINCT FROM 'terminee') THEN
        PERFORM public.examens_blancs_valider_si_complet(NEW.apprenant_id, NEW.exam_id);
      END IF;
    END IF;
  EXCEPTION WHEN others THEN
    -- Ne bloque jamais la remise d'un examen.
    RAISE WARNING 'examens_blancs_6_sur_6: %', SQLERRM;
  END;
  RETURN NULL;
END;
$function$

