functions.qrc_ia_enfiler:
CREATE OR REPLACE FUNCTION public.qrc_ia_enfiler(p_attempt uuid, p_origine text DEFAULT 'serveur'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r text; s public.qrc_ia_suites; ins uuid;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' AND current_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'Service uniquement' USING ERRCODE='42501'; END IF;
 r := public.qrc_ia_raison_file(p_attempt);
 IF r<>'admissible' THEN
  IF r IN ('rien_a_corriger','hors_periode') THEN
   UPDATE public.qrc_ia_suites qcs SET statut='a_verifier',
    message='QRC encore en attente mais non admissibles à une reprise automatique',
    dernier_code='qrc_en_attente_non_admissible', maj_at=now()
    WHERE qcs.attempt_id=p_attempt AND qcs.statut='terminee'
      AND EXISTS(SELECT 1 FROM public.qrc_instances_v2 q WHERE q.attempt_id=p_attempt AND q.etat='en_attente')
   RETURNING qcs.attempt_id INTO ins;
   IF ins IS NOT NULL THEN
    INSERT INTO public.alertes_systeme(type,titre,message,details,lu) VALUES(
     'qrc_ia_suite','Correction QRC à vérifier',
     'La file était terminée à tort alors que des QRC restent en attente ; aucune note ni nouvel appel IA.',
     jsonb_build_object('attempt_id',p_attempt,'code','qrc_en_attente_non_admissible')::text,false);
    RETURN 'revue_qrc_en_attente';
   END IF;
  END IF;
  RETURN r;
 END IF;
 INSERT INTO public.qrc_ia_suites(attempt_id, origine, maj_at, dernier_code) VALUES(p_attempt, left(p_origine,40), now(), 'en_file')
 ON CONFLICT (attempt_id) DO NOTHING RETURNING attempt_id INTO ins;
 IF ins IS NOT NULL THEN RETURN 'en_file'; END IF;
 SELECT * INTO s FROM public.qrc_ia_suites WHERE attempt_id=p_attempt FOR UPDATE;
 IF s.statut IN ('attente','en_cours') THEN RETURN 'deja_en_file'; END IF;
 IF s.statut='terminee' OR (s.statut='pause' AND EXISTS(SELECT 1 FROM public.qrc_ia_config WHERE id AND actif AND pause_depuis IS NULL)) THEN
  IF s.remaining<=0 THEN
   UPDATE public.qrc_ia_suites SET statut='a_verifier', message='Budget épuisé alors que des QRC admissibles restent', dernier_code='budget_epuise', maj_at=now() WHERE attempt_id=p_attempt;
   INSERT INTO public.alertes_systeme(type,titre,message,details,lu) VALUES('qrc_ia_suite','Correction QRC à vérifier','Budget de continuation épuisé avec des QRC restantes.',jsonb_build_object('attempt_id',p_attempt,'code','budget_epuise')::text,false);
   RETURN 'revue_budget';
  END IF;
  UPDATE public.qrc_ia_suites SET statut='attente', next_at=now(), dispatches=0, lease_until=NULL,
   message='Réouverte ('||left(p_origine,40)||') : QRC admissibles sans trace', dernier_code='reouverte', maj_at=now() WHERE attempt_id=p_attempt;
  RETURN 'reouverte';
 END IF;
 RETURN 'revue_existante';
END $function$

functions.qrc_ia_raison_file:
CREATE OR REPLACE FUNCTION public.qrc_ia_raison_file(p_attempt uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; a record; ap record;
BEGIN
 SELECT * INTO c FROM public.qrc_ia_config WHERE id;
 IF NOT FOUND OR NOT c.actif OR c.actif_depuis IS NULL THEN RETURN 'ia_desactivee'; END IF;
 SELECT attempt_id, apprenant_id, etat, finished_at, is_test INTO a FROM public.exam_attempts_v2 WHERE attempt_id=p_attempt;
 IF NOT FOUND THEN RETURN 'passage_introuvable'; END IF;
 IF a.etat<>'terminee' OR a.finished_at IS NULL THEN RETURN 'passage_non_termine'; END IF;
 IF a.apprenant_id='c0844007-b999-4385-9665-918e5077c3b5' THEN RETURN 'exclu'; END IF;
 SELECT type_apprenant,modalite_formation,nom,prenom,email,compte_cours_archive_at INTO ap FROM public.apprenants WHERE id=a.apprenant_id;
 IF NOT FOUND OR NOT public.qrc_ia_type_elearning(ap.type_apprenant,ap.modalite_formation) THEN RETURN 'non_elearning'; END IF;
 IF ap.compte_cours_archive_at IS NOT NULL THEN RETURN 'compte_archive'; END IF;
 IF a.is_test OR EXISTS(SELECT 1 FROM public.comptes_test_techniques t WHERE t.apprenant_id=a.apprenant_id)
    OR public.qrc_ia_identite_compte_test(ap.nom,ap.prenom,ap.email) THEN RETURN 'compte_test'; END IF;
 IF EXISTS(SELECT 1 FROM public.core_tentatives_neutralisees n WHERE n.attempt_id=p_attempt)
    OR EXISTS(SELECT 1 FROM public.core_exam_resets r WHERE r.archived_attempt_ids ? p_attempt::text) THEN RETURN 'passage_archive_ou_neutralise'; END IF;
 IF a.finished_at < greatest(c.actif_depuis,timestamptz '2026-10-20 09:53+00')
    AND NOT EXISTS(SELECT 1 FROM public.qrc_ia_rattrapages_historiques h WHERE h.attempt_id=p_attempt) THEN RETURN 'hors_periode'; END IF;
 IF NOT EXISTS(
   SELECT 1 FROM public.qrc_instances_v2 q
   WHERE q.attempt_id=p_attempt AND q.etat='en_attente' AND q.reponse IS NOT NULL
     AND NOT EXISTS(SELECT 1 FROM public.qrc_ia_reprises r WHERE r.qrc_instance_id=q.qrc_instance_id)
     AND (NOT EXISTS(SELECT 1 FROM public.qrc_ia_corrections x WHERE x.qrc_instance_id=q.qrc_instance_id)
       OR EXISTS(SELECT 1 FROM public.qrc_ia_corrections x WHERE x.qrc_instance_id=q.qrc_instance_id AND x.statut='exclue' AND x.motif='matiere_exclue_gt'))
 ) THEN RETURN 'rien_a_corriger'; END IF;
 RETURN 'admissible';
END $function$

functions.garde_donnee_eleve:
CREATE OR REPLACE FUNCTION public.garde_donnee_eleve()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mode text := TG_ARGV[0];
  v_row jsonb := to_jsonb(OLD);
  v_app uuid;
  v_test boolean := false;
  v_bypass boolean := coalesce(current_setting('app.suppression_eleve_autorisee', true), '') = 'on';
  v_refuse boolean;
BEGIN
  BEGIN
    v_app := nullif(CASE WHEN TG_TABLE_NAME='apprenants' THEN v_row->>'id' ELSE v_row->>'apprenant_id' END, '')::uuid;
  EXCEPTION WHEN others THEN v_app := NULL; END;
  IF v_app IS NOT NULL THEN
    BEGIN v_test := coalesce(public.est_compte_test(v_app), false); EXCEPTION WHEN others THEN v_test := false; END;
  END IF;
  v_refuse := CASE v_mode
    WHEN 'refuser' THEN true
    WHEN 'signature' THEN coalesce(v_row->>'type_document','') ~* '(emarg|signat)'
    ELSE false END;
  IF v_refuse AND NOT v_bypass AND NOT v_test THEN
    RAISE EXCEPTION USING ERRCODE='P0520',
      MESSAGE = format('Donnée élève protégée (%s) : suppression interdite. Aucune donnée élève ne doit disparaître.', TG_TABLE_NAME);
  END IF;
  INSERT INTO public.donnees_eleves_suppressions(table_nom, apprenant_id, ligne, auteur_uid, auteur_role, compte_test, motif)
  VALUES (TG_TABLE_NAME, v_app, v_row, auth.uid(), current_user, v_test,
          CASE WHEN v_bypass THEN 'autorisation SQL explicite' WHEN v_test THEN 'compte de test' ELSE 'suppression autorisée (table non bloquante)' END);
  RETURN OLD;
END $function$

functions.garde_quiz_equipements_taxi_v1:
CREATE OR REPLACE FUNCTION public.garde_quiz_equipements_taxi_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE k text; nb int[] := ARRAY[3,3,3,3,3,3,3,3,3,3,3,3,3,3,3]; n int;
BEGIN
  IF NEW.exercice_id <> 'quiz_taxi_locale_equipements_v1' THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.completed IS TRUE AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'Quiz Équipements TAXI déjà terminé : preuve conservée' USING ERRCODE='42501';
  END IF;
  IF NEW.score IS NOT NULL THEN RAISE EXCEPTION 'Quiz Équipements TAXI non noté' USING ERRCODE='23514'; END IF;
  IF NEW.reponses->>'version' IS DISTINCT FROM '2026-10-27-v1' OR jsonb_typeof(NEW.reponses->'valeurs') IS DISTINCT FROM 'object'
    OR coalesce(NEW.reponses->>'revision','')='' THEN
    RAISE EXCEPTION 'Version ou identité de saisie manquante' USING ERRCODE='23514';
  END IF;
  IF NEW.completed IS TRUE THEN
    FOR n IN 1..15 LOOP
      k := 'q'||lpad(n::text,2,'0');
      IF jsonb_typeof(NEW.reponses->'valeurs'->k) IS DISTINCT FROM 'string'
        OR NEW.reponses->'valeurs'->>k !~ '^[0-9]$'
        OR (NEW.reponses->'valeurs'->>k)::int >= nb[n] THEN
        RAISE EXCEPTION 'Quiz Équipements TAXI incomplet : %', k USING ERRCODE='23514';
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $function$

